from pathlib import Path
from docx import Document
from docx.shared import Cm, Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

OUT = Path('output')
OUT.mkdir(exist_ok=True)


def shade(cell, fill='D9EAF7'):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement('w:shd')
    shd.set(qn('w:fill'), fill)
    tcPr.append(shd)


def setup():
    d = Document()
    s = d.sections[0]
    s.left_margin = Cm(3); s.right_margin = Cm(1.5)
    s.top_margin = Cm(2); s.bottom_margin = Cm(2)
    normal = d.styles['Normal']
    normal.font.name = 'Times New Roman'
    normal._element.rPr.rFonts.set(qn('w:eastAsia'), 'Times New Roman')
    normal.font.size = Pt(14)
    normal.paragraph_format.line_spacing = 1.5
    normal.paragraph_format.space_after = Pt(0)
    normal.paragraph_format.first_line_indent = Cm(1.25)
    normal.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    for name, size in [('Title',18),('Heading 1',16),('Heading 2',14),('Heading 3',14)]:
        st=d.styles[name]; st.font.name='Times New Roman'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman')
        st.font.size=Pt(size); st.font.bold=True; st.paragraph_format.keep_with_next=True
        st.paragraph_format.space_before=Pt(8); st.paragraph_format.space_after=Pt(6)
        if name=='Heading 1': st.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.CENTER
    h=s.header.paragraphs[0]; h.text='ООО «Экспальянс» | ДПП ПК «Ведение бизнеса с Китаем» | 144 акад. ч.'; h.alignment=WD_ALIGN_PARAGRAPH.CENTER
    for r in h.runs: r.font.name='Times New Roman'; r.font.size=Pt(9)
    f=s.footer.paragraphs[0]; f.alignment=WD_ALIGN_PARAGRAPH.CENTER
    r=f.add_run('Страница '); r.font.name='Times New Roman'; r.font.size=Pt(10)
    b=OxmlElement('w:fldChar'); b.set(qn('w:fldCharType'),'begin')
    i=OxmlElement('w:instrText'); i.set(qn('xml:space'),'preserve'); i.text='PAGE'
    e=OxmlElement('w:fldChar'); e.set(qn('w:fldCharType'),'end')
    r._r.extend([b,i,e])
    return d


def p(d, text, center=False, noindent=False, bold=False):
    x=d.add_paragraph(); x.alignment=WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.JUSTIFY
    if noindent: x.paragraph_format.first_line_indent=Cm(0)
    rr=x.add_run(text); rr.bold=bold
    return x


def bullets(d, items, numbered=False):
    style='List Number' if numbered else 'List Bullet'
    for item in items:
        x=d.add_paragraph(style=style); x.paragraph_format.left_indent=Cm(.7); x.paragraph_format.first_line_indent=Cm(-.4); x.add_run(item)


def table(d, headers, rows):
    t=d.add_table(rows=1, cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for j,h in enumerate(headers):
        c=t.rows[0].cells[j]; c.text=h; shade(c); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        for pp in c.paragraphs:
            pp.alignment=WD_ALIGN_PARAGRAPH.CENTER; pp.paragraph_format.first_line_indent=Cm(0)
            for r in pp.runs: r.bold=True; r.font.name='Times New Roman'; r.font.size=Pt(10.5)
    for row in rows:
        cells=t.add_row().cells
        for j,val in enumerate(row):
            cells[j].text=str(val); cells[j].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.TOP
            for pp in cells[j].paragraphs:
                pp.paragraph_format.first_line_indent=Cm(0); pp.paragraph_format.line_spacing=1.15
                for r in pp.runs: r.font.name='Times New Roman'; r.font.size=Pt(10.5)
    d.add_paragraph()


def title_page(d, n, name, hours):
    d.add_heading('1. Титульный лист.',1)
    p(d,'ОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ\n«ЭКСПАЛЬЯНС»',True,True,True)
    d.add_paragraph(); d.add_paragraph()
    p(d,'ДОПОЛНИТЕЛЬНАЯ ПРОФЕССИОНАЛЬНАЯ ПРОГРАММА\nПОВЫШЕНИЯ КВАЛИФИКАЦИИ',True,True,True)
    p(d,'«ВЕДЕНИЕ БИЗНЕСА С КИТАЕМ»',True,True,True)
    d.add_paragraph()
    p(d,f'ЛЕКЦИЯ\nМОДУЛЬ {n}. {name.upper()}',True,True,True)
    d.add_paragraph()
    p(d,f'Трудоёмкость модуля: {hours} академических часов\nКатегория слушателей: руководители организаций, предприниматели, специалисты ВЭД\nФорма обучения: заочная с применением электронного обучения и дистанционных образовательных технологий',True,True)
    for _ in range(5): d.add_paragraph()
    p(d,'г. Камбарка\n2026',True,True)
    d.add_page_break()


def front(d, annotation, goal, tasks, know, can, own, plan):
    d.add_heading('2. Аннотация.',1); p(d,annotation)
    d.add_heading('3. Цель лекции.',1); p(d,goal)
    d.add_heading('4. Задачи лекции.',1); bullets(d,tasks)
    d.add_heading('5. Планируемые результаты обучения.',1)
    d.add_heading('Знать',2); bullets(d,know)
    d.add_heading('Уметь',2); bullets(d,can)
    d.add_heading('Владеть',2); bullets(d,own)
    d.add_heading('6. План лекции.',1); bullets(d,plan,True)
    d.add_page_break()
    d.add_heading('7. Основной текст лекции.',1)


def topic(d, head, paras, page=False):
    d.add_heading(head,2)
    for text in paras: p(d,text)
    if page: d.add_page_break()


def ending(d, questions, assignment, criteria, terms, recs, conclusion, sources):
    d.add_heading('9. Контрольные вопросы.',1); bullets(d,questions,True)
    d.add_page_break()
    d.add_heading('10. Практическое задание.',1)
    for x in assignment: p(d,x)
    d.add_heading('11. Критерии оценивания.',1); table(d,['Критерий','Баллы','Признаки качественного выполнения'],criteria)
    p(d,'Рекомендуемый порог зачёта — 70 баллов из 100. При недостаточном результате работа дорабатывается с учётом замечаний и представляется повторно.')
    d.add_page_break()
    d.add_heading('12. Термины и определения.',1); table(d,['Термин','Определение'],terms)
    d.add_heading('13. Методические рекомендации слушателю.',1); bullets(d,recs)
    d.add_heading('14. Заключение.',1); p(d,conclusion)
    d.add_heading('15. Список источников.',1); bullets(d,sources,True)


